export const logoPaths = Object.fromEntries(
  Object.entries(logoFiles).map(([id, file]) => [
    id,
    (import.meta.env?.BASE_URL || "/") + "logos/" + file,
  ]),
);
export const normalizeSearch = (value) =>
  String(value)
    .normalize("NFKC")
    .toLocaleLowerCase("ko-KR")
    .replace(/[^\p{L}\p{N}]/gu, "");
export function matchesService(service, query) {
  const needle = normalizeSearch(query);
  if (!needle) return true;
  const known = catalog.find(
    (item) => item.id === (service.serviceId || service.id),
  );
  return [service.name, service.alias, known?.name, known?.alias]
    .filter(Boolean)
    .some((value) => normalizeSearch(value).includes(needle));
}
